Slot: ${item.slotIndex} (${item.windowLabel})
Facebook Post ID: ${item.post_id}

Headline: ${item.title}
Source: ${item.source?.name}
Article: ${item.url}

Image: ${item.imageSource}
Quality score: ${item.audit?.quality_score ?? 'n/a'}/10
Compliance: ${item.audit?.compliance_status ?? 'n/a'}

View Page: https://www.facebook.com/${pageId}`,
  }
